class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Generate all substrings of s (including empty string)
        subs_s = [""]
        n = len(s)
        for i in range(n):
            for j in range(i + 1, n + 1):
                subs_s.append(s[i:j])

        # Generate all substrings of t (including empty string)
        subs_t = [""]
        m = len(t)
        for i in range(m):
            for j in range(i + 1, m + 1):
                subs_t.append(t[i:j])

        max_len = 0

        for a in subs_s:
            la = len(a)
            # Pruning: even if we take the longest possible from t, can't improve
            if la + m <= max_len:
                continue
            for b in subs_t:
                lb = len(b)
                if la + lb <= max_len:
                    continue

                # Check if a + b is a palindrome using two pointers
                total = la + lb
                left, right = 0, total - 1
                is_pal = True
                while left < right:
                    # character at left position
                    if left < la:
                        c_left = a[left]
                    else:
                        c_left = b[left - la]

                    # character at right position
                    if right < la:
                        c_right = a[right]
                    else:
                        c_right = b[right - la]

                    if c_left != c_right:
                        is_pal = False
                        break
                    left += 1
                    right -= 1

                if is_pal:
                    max_len = total

        return max_len
