import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out_lines = []
    for _ in range(t):
        n = int(data[idx]); idx += 1
        A = [int(data[idx + i]) for i in range(2 * n)]
        idx += 2 * n

        L = [0] * (n + 1)
        R = [0] * (n + 1)
        for pos, val in enumerate(A, start=1):
            if L[val] == 0:
                L[val] = pos
            else:
                R[val] = pos

        non_adj = [False] * (n + 1)
        for x in range(1, n + 1):
            if R[x] != L[x] + 1:
                non_adj[x] = True

        # map left position to couple id for non-adjacent couples
        pos_to_x = [0] * (2 * n + 2)
        for x in range(1, n + 1):
            if non_adj[x]:
                pos_to_x[L[x]] = x

        ans = 0
        for x in range(1, n + 1):
            if non_adj[x]:
                nxt = L[x] + 1
                if nxt <= 2 * n:
                    y = pos_to_x[nxt]
                    if y != 0 and non_adj[y] and abs(R[x] - R[y]) == 1:
                        ans += 1
        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
