from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # Precompute powers of 4 up to > 1e9
        pow4 = [1]
        while pow4[-1] <= 10**9:
            pow4.append(pow4[-1] * 4)
        # pow4[i] = 4^i

        def f(x: int) -> int:
            # Number of divisions by 4 needed to reduce x to 0.
            # Equivalent to the number of base-4 digits of x.
            for k in range(1, len(pow4)):
                if x < pow4[k]:
                    return k
            return len(pow4) - 1

        def prefix_sum(n: int) -> int:
            # Sum of f(x) for x = 1..n
            if n <= 0:
                return 0
            total = 0
            for k in range(1, len(pow4)):
                start = pow4[k - 1]
                if start > n:
                    break
                end = min(pow4[k] - 1, n)
                total += k * (end - start + 1)
            return total

        ans = 0
        for l, r in queries:
            max_f = f(r)
            sum_f = prefix_sum(r) - prefix_sum(l - 1)
            ops = max(max_f, (sum_f + 1) // 2)
            ans += ops
        return ans
