class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # Collect all distinct positive numbers
        distinct_positives = set()
        for num in nums:
            if num > 0:
                distinct_positives.add(num)

        # If there is at least one positive number, we can take all distinct positives
        # by deleting everything else, achieving the maximum possible sum.
        if distinct_positives:
            return sum(distinct_positives)

        # Otherwise, all numbers are non-positive. We must pick at least one element,
        # so we pick the maximum (least negative or zero).
        return max(nums)
