from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        tree = [0] * (4 * n)

        def build(node: int, l: int, r: int) -> None:
            if l == r:
                tree[node] = baskets[l]
            else:
                mid = (l + r) // 2
                build(node * 2, l, mid)
                build(node * 2 + 1, mid + 1, r)
                tree[node] = max(tree[node * 2], tree[node * 2 + 1])

        def update(node: int, l: int, r: int, idx: int, val: int) -> None:
            if l == r:
                tree[node] = val
            else:
                mid = (l + r) // 2
                if idx <= mid:
                    update(node * 2, l, mid, idx, val)
                else:
                    update(node * 2 + 1, mid + 1, r, idx, val)
                tree[node] = max(tree[node * 2], tree[node * 2 + 1])

        def query_first(node: int, l: int, r: int, x: int) -> int:
            """Return leftmost index in [l, r] with value >= x, or -1 if none."""
            if tree[node] < x:
                return -1
            if l == r:
                return l
            mid = (l + r) // 2
            if tree[node * 2] >= x:
                return query_first(node * 2, l, mid, x)
            else:
                return query_first(node * 2 + 1, mid + 1, r, x)

        build(1, 0, n - 1)
        unplaced = 0

        for fruit in fruits:
            idx = query_first(1, 0, n - 1, fruit)
            if idx == -1:
                unplaced += 1
            else:
                update(1, 0, n - 1, idx, -1)  # mark basket as used

        return unplaced
