class Solution:
    dp = None

    def beautifulNumbers(self, l: int, r: int) -> int:
        if Solution.dp is None:
            Solution.dp = self._precompute_dp()
        dp = Solution.dp

        def count_no_zero(n: int) -> int:
            if n == 0:
                return 0
            s = str(n)
            L = len(s)
            count = 0
            for length in range(1, L):
                count += 9 ** length
            for i, ch in enumerate(s):
                d = int(ch)
                for digit in range(1, d):
                    count += 9 ** (L - i - 1)
                if d == 0:
                    return count
            return count + 1

        def count_beautiful_no_zero(n: int) -> int:
            if n == 0:
                return 0
            s = str(n)
            L = len(s)
            count = 0
            # lengths smaller than L
            for length in range(1, L):
                for (s_sum, p), cnt in dp[length].items():
                    if p % s_sum == 0:
                        count += cnt
            # length equal to L
            pref_sum = 0
            pref_prod = 1
            for i, ch in enumerate(s):
                d = int(ch)
                for digit in range(1, d):
                    new_sum = pref_sum + digit
                    new_prod = pref_prod * digit
                    rem = L - i - 1
                    for (suf_sum, suf_prod), cnt in dp[rem].items():
                        total_sum = new_sum + suf_sum
                        total_prod = new_prod * suf_prod
                        if total_prod % total_sum == 0:
                            count += cnt
                if d == 0:
                    return count
                pref_sum += d
                pref_prod *= d
            if pref_prod % pref_sum == 0:
                count += 1
            return count

        def beautiful_up_to(n: int) -> int:
            if n == 0:
                return 0
            total = n
            no_zero = count_no_zero(n)
            beautiful_no_zero = count_beautiful_no_zero(n)
            return total - no_zero + beautiful_no_zero

        return beautiful_up_to(r) - beautiful_up_to(l - 1)

    @staticmethod
    def _precompute_dp():
        dp = [{} for _ in range(10)]
        dp[0] = {(0, 1): 1}
        for length in range(1, 10):
            prev = dp[length - 1]
            cur = {}
            for (s, p), cnt in prev.items():
                for d in range(1, 10):
                    ns = s + d
                    np = p * d
                    key = (ns, np)
                    cur[key] = cur.get(key, 0) + cnt
            dp[length] = cur
        return dp
